@Composable fun MealCommerceControls(state:BuddyState,vm:BuddyViewModel,from:String){
 val root=state.meals?:return;val kitchen=root["state"]!!.jsonObject;val needs=root["shopping"]!!.jsonObject.mealRows("needs");val context=LocalContext.current
