 MealChoice(mealText("Country","Pays"),listOf("FR" to "France","US" to mealText("United States","États-Unis")),country,{country=it});MealField(mealText("Service location · postcode","Lieu de service · code postal"),location,{location=it});MealChoice(mealText("Fulfilment","Réception"),listOf("delivery" to mealText("Delivery","Livraison"),"pickup" to mealText("Pickup","Retrait")),fulfilment,{fulfilment=it})
 Text(if(country=="FR")mealText("France checkout awaits approved retailer partner access. Manual shopping is available.","Le paiement en France attend un accès partenaire agréé. Les achats manuels sont disponibles.")else mealText("US: Instacart development handoff requires credentials. Review store, products, prices, fees, slots and purchase at the retailer. No location has been verified for Recipe Buddy.","États-Unis : le transfert Instacart de développement nécessite des identifiants. Vérifiez magasin, produits, prix, frais, créneau et achat chez le commerçant. Aucun lieu vérifié pour Recipe Buddy."))
 needs.forEach{n->val key=n.mealValue("name").lowercase().trim()+"|"+n.mealValue("unit");Row{Checkbox(selected.contains(key),{selected=if(it)selected+key else selected-key});Text(n.mealValue("name")+": "+n.mealValue("quantity",mealText("Unknown","Inconnue"))+" "+n.mealValue("unit"))}}
 KitchenButton(enabled=!state.busy&&selected.isNotEmpty()&&location.isNotBlank(),onClick={vm.mealChange("prepare-basket",buildJsonObject{put("id",UUID.randomUUID().toString());put("country",country);put("acknowledgeIncoming",acknowledgeIncoming);put("location",location);put("fulfilment",fulfilment);put("from",from);put("to",LocalDate.parse(from).plusDays(6).toString());put("selected",JsonArray(selected.map(::JsonPrimitive)));put("diners",JsonArray(emptyList()))})}){Text(mealText("Prepare selected list","Préparer la liste choisie"))}
 kitchen.mealRows("baskets").forEach{b->
 Text(b.mealValue("country")+" · "+b.mealValue("location"),style=MaterialTheme.typography.titleMedium);Text(when(b.mealValue("status")){"prepared"->mealText("Prepared list","Liste préparée");"retailer-handoff"->mealText("Retailer handoff · no order evidence","Transfert commerçant · aucune preuve de commande");"manually-confirmed-order"->mealText("Incoming · order reported by you","Attendu · commande déclarée par vous");"partially-received"->mealText("Partially received","Reçu partiellement");"received"->mealText("Received","Reçu");"cancelled"->mealText("Cancelled · stock unchanged","Annulé · stock inchangé");else->mealText("Handoff response unknown","Réponse du transfert inconnue")})
 b.mealRows("items").forEach{Text(it.mealValue("name")+": "+it.mealValue("quantity",mealText("Unknown","Inconnue"))+" "+it.mealValue("unit"))}
 Text(mealText("Exact products, package counts, prices, fees, slots and substitution controls are unavailable here. Review at the retailer; changed products need new label checks.","Produits exacts, emballages, prix, frais, créneaux et substitutions indisponibles ici. Vérifiez chez le commerçant et revérifiez les étiquettes des substitutions."))
 if(b.mealValue("provider")=="instacart"&&b.mealValue("status")=="prepared")KitchenOutlinedButton(enabled=!state.busy,onClick={vm.prepareMealHandoff(b.mealValue("id"))}){Text(mealText("Prepare retailer handoff · review required","Préparer le transfert · vérification requise"))}
