@Composable private fun MealOrderReconcile(b:JsonObject,state:BuddyState,vm:BuddyViewModel){
 var open by rememberSaveable(b.mealValue("id")){mutableStateOf(false)};var reference by rememberSaveable(b.mealValue("id")){mutableStateOf(b.mealValue("providerOrderId"))};var notes by rememberSaveable(b.mealValue("id")){mutableStateOf("")};var status by rememberSaveable(b.mealValue("id")){mutableStateOf("manually-confirmed-order")}
 KitchenTextButton(onClick={open=!open}){Text(mealText("Reconcile retailer order manually","Rapprocher la commande manuellement"))};if(open){Text(mealText("Use actual retailer confirmation. A redirect is not purchase evidence. Refund alone changes no stock.","Utilisez la confirmation réelle du commerçant. Un lien ouvert ne prouve pas l’achat. Un remboursement seul ne change pas le stock."));MealField(mealText("Retailer order reference","Référence de commande"),reference,{reference=it});MealField(mealText("Evidence / notes","Preuve / notes"),notes,{notes=it});MealChoice(mealText("Actual status","Statut réel"),listOf("manually-confirmed-order" to mealText("Order confirmed by you","Commande confirmée par vous"),"cancelled" to mealText("Cancelled / refunded","Annulé / remboursé"),"received" to mealText("Receipt completed","Réception terminée")),status,{status=it});KitchenButton(enabled=!state.busy&&notes.isNotBlank()&&(status!="manually-confirmed-order"||reference.isNotBlank()),onClick={vm.mealChange("reconcile-order",buildJsonObject{put("id",b.mealValue("id"));put("status",status);put("providerOrderId",reference);put("notes",notes)})}){Text(mealText("Save reported order status","Enregistrer le statut déclaré"))}}
}
@Composable private fun MealOrderReceive(b:JsonObject,state:BuddyState,vm:BuddyViewModel){
 var open by rememberSaveable(b.mealValue("id")){mutableStateOf(false)};var name by rememberSaveable(b.mealValue("id")){mutableStateOf("")};var quantity by rememberSaveable(b.mealValue("id")){mutableStateOf("")};var unit by rememberSaveable(b.mealValue("id")){mutableStateOf("g")};var label by rememberSaveable(b.mealValue("id")){mutableStateOf("")};var complete by rememberSaveable(b.mealValue("id")){mutableStateOf(false)};var receiptId by rememberSaveable(b.mealValue("id")){mutableStateOf(UUID.randomUUID().toString())}
 LaunchedEffect(b){if(b["receivedBatchIds"]?.jsonArray?.any{it.jsonPrimitive.content==receiptId}==true){name="";quantity="";receiptId=UUID.randomUUID().toString()}}
 KitchenTextButton(onClick={open=!open}){Text(mealText("Confirm actual receipt","Confirmer la réception réelle"))};if(open){Text(mealText("Enter each received product and amount, including substitutes. Missing/damaged goods add no stock. Check labels; cross-contact remains unknown.","Saisissez chaque produit et quantité reçus, substitutions comprises. Produits absents ou endommagés : aucun stock ajouté. Vérifiez les étiquettes, contamination croisée inconnue."));MealField(mealText("Actual product","Produit réel"),name,{name=it});MealField(mealText("Actual quantity","Quantité réelle"),quantity,{quantity=it});MealField(mealText("Unit","Unité"),unit,{unit=it});MealField(mealText("Composition & allergens","Composition et allergènes"),label,{label=it});Row{Checkbox(complete,{complete=it});Text(mealText("All actual receipt items recorded","Tous les produits reçus sont enregistrés"))};KitchenButton(enabled=!state.busy&&name.isNotBlank()&&quantity.toDoubleOrNull()?.let{it>0}==true,onClick={vm.mealChange("receive-order",buildJsonObject{put("id",receiptId);put("basketId",b.mealValue("id"));put("batch",buildJsonObject{put("id",receiptId);put("name",name);put("quantity",quantity.toDouble());put("unit",unit);put("label",label)});put("complete",complete);put("notes","Manual actual receipt")})}){Text(mealText("Add received stock once","Ajouter le stock reçu une fois"))};Text(mealText("For actual returns/discarding, correct the actual batch in Pantry. Refund alone changes no stock.","Pour un retour ou une mise au rebut réels, corrigez le lot dans Stock. Un remboursement seul ne modifie pas le stock."))}
